arguments.command:
cat > /tmp/git-askpass.sh <<'EOF'
#!/bin/sh
case "$1" in
  *sername*) printf 'x-access-token\n' ;;
  *) printf '%s\n' "$GITHUB_TOKEN" ;;
esac
EOF
chmod +x /tmp/git-askpass.sh
cd /home/runner/work/phoebe-convo && GIT_ASKPASS=/tmp/git-askpass.sh GIT_TERMINAL_PROMPT=0 git push origin HEAD:refs/heads/friend/phoebe 2>&1 | tail -5
